\label{prop:tight}
	Suppose that $\{ {\textnormal{U}}_{n}(\cdot) \}_{n=0}^\infty$ is a tight sequence of random functions in $C([0, \infty); {\mathbb R}^{d})$ 
	and ${\textnormal{U}}(\cdot)$ is another random function in $C([0, \infty); {\mathbb R}^{d})$. 

	\begin{enumerate}[(i)]
		\item \label{prop:tight:fdd}


		If the finite-dimensional distributions of $ {\textnormal{U}}_{n}(\cdot) $ converge weakly to the finite-dimensional distributions of ${\textnormal{U}}(\cdot)$, i.e., for each positive integer $k$ and positive numbers $t_1, t_2, \dots, t_k > 0$, it holds that $({\textnormal{U}}_{n}(t_1), {\textnormal{U}}_{n}(t_2), \dots, {\textnormal{U}}_{n}(t_k)) \Rightarrow ({\textnormal{U}}(t_1), {\textnormal{U}}(t_2), \dots, {\textnormal{U}}(t_k))$, then ${\textnormal{U}}_{n}(\cdot) \Rightarrow {\textnormal{U}}(\cdot)$ {\citep[Theorem~3]{whitt1970weak}}.

		\item \label{prop:tight:prok} Prokhorov's theorem {\citep[Theorem~5.1]{billingsley2013convergence}}: Each subsequence of $\{ {\textnormal{U}}_{n}(\cdot) \}_{n=0}^\infty$ contains a further subsequence that converges weakly to some random function in $C([0, \infty); {\mathbb R}^{d})$.
		\item \label{prop:tight:converge} If each convergent subsequence of $\{ {\textnormal{U}}_{n}(\cdot) \}_{n=0}^\infty$ converges weakly to ${\textnormal{U}}(\cdot)$, then ${\textnormal{U}}_{n}(\cdot) \Rightarrow {\textnormal{U}}(\cdot)$ \citep[Corollary on page~59]{billingsley2013convergence}.

	\end{enumerate}

\label{def:mart_prob}
	Suppose ${\mathcal A}\colon \mathrm{dom}(A) \subseteq C_b({\mathbb R}^d) \rightarrow C_b({\mathbb R}^d) $ is a linear operator, $L \subseteq \mathrm{dom} ({\mathcal A})$ is the set of test functions, and ${\textnormal{U}}(\cdot)$ is a $({\mathcal F}_t)_{t \ge 0}$-adapted stochastic process. 
	We say ${\textnormal{U}}(\cdot)$ solves the \textit{martingale problem} for $({\mathcal A}, L)$, if for any $f \in L$, the following process
	\begin{equation}\label{eq:mart-prob}
		f({\textnormal{U}}(t)) - f({\textnormal{U}}(0)) - \int_0^t {\mathcal A} f({\textnormal{U}}(s)) ds
	\end{equation}
	 is a martingale w.r.t.\ to filtration $({\mathcal F}_t)_{t \ge 0}$.

\begin{equation}\label{eq:mart-prob}
		f({\textnormal{U}}(t)) - f({\textnormal{U}}(0)) - \int_0^t {\mathcal A} f({\textnormal{U}}(s)) ds
	\end{equation}

Consequently, when we refer to the solution of \eqref{eq:sde-general}, we mean the \textit{weak solution}, without explicitly detailing the probability space of the stochastic process.}
