\label{thm:fclt-twotime}
	Suppose that Assumptions~\ref{assump:smooth} -- \ref{assump:noise-fclt} and \ref{assump:mart-decouple-rate} hold.
	\begin{enumerate}[(i)]
		\item \label{thm:fclt-x} The stochastic process ${\bar{\textnormal{X}}}_{n}(\cdot)$ defined in \eqref{eq:xbar-short} converges weakly to the stationary solution of the following SDE 
		\begin{equation}\label{eq:fclt-twotime:x-sde}
			d {\textnormal{X}}(t) = - B_1 {\textnormal{X}}(t) dt + \Sigma_{\xi}^{1/2} d {\textnormal{W}}^{d_x}(t).
		\end{equation}
		The rescaled iterate $ {\check{x}}_{n} $ defined in \eqref{eq:xycheck-def} converges weakly to the invariant distribution of \eqref{eq:fclt-twotime:x-sde}, i.e., ${\mathcal N}(0, \Sigma_x)$, where $\Sigma_x$ satisfies the following Lyapunov equation 
		\begin{equation}\label{eq:fclt-twotime:x-var}
			B_1 \Sigma_x + \Sigma_x B_1 = \Sigma_{\xi}.
		\end{equation}





		\item \label{thm:fclt-y} The stochastic process ${\bar{\textnormal{Y}}}_{n}(\cdot)$ defined in \eqref{eq:ybar-short} converges weakly to the stationary solution of the following SDE 
		\begin{equation}\label{eq:fclt-twotime:y-sde}
			d {\textnormal{Y}}(t) = - \left(B_3 - \frac{\tilde{\beta} {I}}{2}  \right) {\textnormal{Y}}(t) dt + \widetilde{\Sigma}_{\psi}^{1/2} d {\textnormal{W}}^{d_y}(t),
		\end{equation}
		where the matrix $\widetilde{\Sigma}_{\psi}$ is defined as 
		\begin{equation}\label{eq:cov-z}
			\widetilde{\Sigma}_{\psi} := \Sigma_{\psi} - B_2 B_1^{-1} \Sigma_{\xi,\psi} - \Sigma_{\xi, \psi}^\top B_1^{-\top} B_2^\top + B_2 B_1^{-1} \Sigma_{\xi} B_1^{-\top} B_2^\top.
		\end{equation}
		The rescaled iterate $ {\check{y}}_{n}$ defined in \eqref{eq:xycheck-def} converges weakly to the invariant distribution of \eqref{eq:fclt-twotime:y-sde}, i.e., ${\mathcal N}(0, \Sigma_y)$, where $\Sigma_y$ satisfies the following Lyapunov equation
		\begin{equation}\label{eq:fclt-twotime:y-var}
			\left(B_3 - \frac{\tilde{\beta} {I}}{2} \right) \Sigma_y + \Sigma_y \left( B_3 - \frac{\tilde{\beta} {I}}{2} \right) = \widetilde{\Sigma}_{\psi}.
		\end{equation}
	\end{enumerate}

