To begin, we take the update rules for ${\hat{x}}_{n}$ and ${\hat{y}}_{n}$, as outlined below.
\begin{align}
    {\hat{x}}_{n+1} & = {\hat{x}}_n - \alpha_n F(x_n, y_n) - \alpha_n \xi_n + H(y_n) - H(y_{n+1}), \label{eq:xhat} \\
    {\hat{y}}_{n+1} & = {\hat{y}}_n - \beta_n G(H(y_n), y_n) + \beta_n ( G(H(y_n), y_n) - G(x_n, y_n) ) - \beta_n \psi_n. \label{eq:yhat}
\end{align}

\textbf{Part 1: one-step recursion for ${\check{y}}_{n}$}.

By Proposition~\ref{prop:operator-decom}, we can rewrite the update rule of ${\hat{y}}_{n}$ in \eqref{eq:yhat} as 
\begin{align}
    \label{eq:yhat-decom}
    {\hat{y}}_{n+1} = (I - \beta_{n} B_3) {\hat{y}}_{n} - \beta_{n} B_2 {\hat{x}}_{n} - \beta_n \psi_n - \beta_n R_n^G.
\end{align}
Then from the definition of ${\check{y}}_{n}$ and \eqref{eq:yhat-decom}, we have 
\begin{align}
    {\check{y}}_{n+1}
    & = \sqrt{ \frac{ \beta_{n-1} }{ \beta_{n} } } ({I} - \beta_{n} B_3) {\check{y}}_{n} - \sqrt{ \beta_{n} \alpha_{n-1} } B_2 {\check{x}}_{n} - \sqrt{\beta_{n}} \psi_{n} - \sqrt{\beta_{n}} R_{n}^G \nonumber \\
    & = \left( {I} - \beta_{n} B_3 + \frac{ \tilde{\beta} \beta_{n} }{2} {I} \right) {\check{y}}_{n} - \sqrt{\beta_{n} \alpha_{n} } B_2 {\check{x}}_{n} - \sqrt{\beta_n} \psi_{n} + R_{n}^y, \label{eq:lem:check-twotime:y-update}
\end{align}
where
\begin{align}\label{eq:lem:check-twotime:Ry}
    \begin{split}
        R_{n}^y
        & =  \underbrace{ \left( \sqrt{ \frac{ \beta_{n-1} }{\beta_{n}} } - 1 - \frac{ \tilde{\beta} \beta_{n} }{2} \right) {\check{y}}_{n} }_{=: R_{n,1}^y}  
        + \underbrace{ ( \beta_{n} - \sqrt{ \beta_{n} \beta_{n-1} } ) B_3 {\check{y}}_{n} 
            \vphantom{ \left( \sqrt{ \frac{ \beta_{n-1} }{\beta_{n}} } \right) } }_{ =:R_{n,2}^y } \\
        & \quad \  + \underbrace{

            ( \sqrt{ 
                \beta_{n} 
                \alpha_{n} } - \sqrt{ 
                \beta_{n} 
                \alpha_{n-1} } ) B_2 {\check{x}}_{n}
            \vphantom{ \left( \sqrt{ \frac{ \beta_{n-1} }{\beta_{n}} } \right) } }_{=: R_{n,3}^y } 
        - \underbrace{ \sqrt{\beta_{n}} R_{n}^G 
            \vphantom{ \left( \sqrt{ \frac{ \beta_{n-1} }{\beta_{n}} } \right) } }_{ =: R_{n,4}^y }.
    \end{split}
\end{align}
By Assumption~\ref{assump:stepsize-twotime}, we have
\begin{align}

        \sqrt{ \frac{ \beta_{n-1} }{ \beta_{n} } } 
        & = \sqrt{ 1 + \beta_{n-1} ( \beta_{n}^{-1} - \beta_{n-1}^{-1} ) } = \sqrt{1 + \tilde{\beta} \beta_{n-1}  + o(\beta_{n-1}) } \nonumber \\
        & = \sqrt{1 + \tilde{\beta} \beta_{n}  + o(\beta_{n}) }
        = 1 + \frac{ \tilde{\beta} \beta_{n} }{2} + o(\beta_{n}), \nonumber \\
        \sqrt{ \frac{ \alpha_{n-1} }{\alpha_{n}} } 
        & = 1 + {\mathcal O}(\beta_n),
        \qquad 
        \sqrt{ \frac{ \kappa_{n-1} }{\kappa_{n}} } 
        = 1 + {\mathcal O}(\beta_n). \label{eq:lem:check-twotime:sqrtalpha}

\end{align}
It follows that $\| R_{n,1}^y \| +  \| R_{n,2}^y \| = o(\beta_{n}) \| {\check{y}}_{n} \| = o(\beta_{n}^{1/2}) \| {\hat{y}}_{n} \|  $
and  $\| R_{n,3}^y \| = {\mathcal O}(\beta_{n}^{3/2} \alpha_{n}^{1/2}) \| {\check{x}}_{n} \| = o(\beta_{n}^{3/2}) \| {\hat{x}}_{n} \| $. 
Meanwhile, by Proposition~\ref{prop:operator-decom}, we have $ \| R_{n,4}^y \| = {\mathcal O}(\beta_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ) $.
Note that in Assumption~\ref{assump:stepsize-twotime}, we require $\alpha_{n}^{1+{\delta_G}} = o(\beta_{n}) $.
Then we have
\begin{align}\label{eq:lem:check-twotime:Ry-upper}
    \| R_{n}^y \| = o(\beta_{n}^{1/2}) \| {\hat{y}}_{n} \| + o(\beta_{n}^{3/2}) \| {\hat{x}}_{n} \| + 

    {\mathcal O}(\beta_{n}) \,

    \frac{ \alpha_{n}^{ (1+{\delta_G}) / 2 } }{ \beta_{n}^{1/2} } \cdot

    \frac{ \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} } {\alpha_{n}^{(1+{\delta_G})/2} }.
\end{align}
By Assumption~\ref{assump:mart-decouple-rate}, it follows that $ {\mathbb E} \| {\mathbb E}[ R_{n}^y | {\mathcal F}_{n} ] \| \le {\mathbb E} \| R_{n}^y \| = o(\beta_{n})$ and ${\mathbb E} \| R_{n}^y \|^2 = o(\beta_{n}^2)$.
Moreover, by Proposition~\ref{prop:FG-reduce-order}, we have that \eqref{eq:lem:check-twotime:Ry-upper} holds with ${\delta_G}$ replaced by ${\delta_G} / 2$.
For $2 \le p \le \frac{4}{1+{\delta_G} / 2}$, it follows that
\begin{align*}
    {\mathbb E} \| R_{n}^y \|^p
    = o(\beta_{n})

    + o( \beta_{n} \cdot  \beta_{n}^{p-1} / \alpha_{n}^{ p {\delta_G} / 2} )
    = o(\beta_{n}),
\end{align*}
where the last step is due to $p-1 \ge p/2 \ge p {\delta_G} / 2$.
\vspace{0.2cm}

\textbf{Part 2: one-step recursion for ${\check{x}}_{n}$}.

By Proposition~\ref{prop:operator-decom}, the update rule of ${\hat{x}}_{n}$ in \eqref{eq:xhat} can be rewritten as
\begin{align}
    {\hat{x}}_{n+1} & = ({I} - \alpha_{n} B_1) {\hat{x}}_{n} + H^\star ({y}_{n} - {y}_{n+1}) - \alpha_{n} \xi_{n} - R_{n}^{\nabla H} - R_{n}^{H} - \alpha_{n} R_{n}^F \nonumber \\ 
    \begin{split}
        & \overset{\eqref{eq:yhat-decom}}{=} ({I} - \alpha_{n} B_1 + \beta_{n} H^\star B_2) {\hat{x}}_{n} + \beta_n H^\star B_3 {\hat{y}}_{n} - \alpha_n \xi_{n} + \beta_{n} H^\star \psi_{n} \\
        & \qquad - R_{n}^{\nabla H} - R_{n}^H - \alpha_{n} R_{n}^F + \beta_n H^\star R_{n}^G. 
    \end{split}
    \label{eq:xhat-decom}
\end{align}
Then from the definition of ${\check{x}}_{n}$, we have
\begin{align}
    {\check{x}}_{n+1}
    & = \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } ({I} - \alpha_{n} B_1 + \beta_n H^\star B_2) {\check{x}}_{n} + \sqrt{ \frac{\beta_{n-1}}{\alpha_{n}} } \beta_{n} H^\star B_3 {\check{y}}_{n} - \sqrt{ \alpha_{n} } \xi_{n} + \frac{ \beta_{n} }{ \sqrt{ \alpha_{n} } } H^\star \psi_{n} \nonumber \\
    & \qquad - \frac{1}{ \sqrt{\alpha_{n}} } R_{n}^{\nabla H} - \frac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} - \sqrt{\alpha_{n}} R_{n}^F + \frac{\beta_{n}}{\sqrt{ \alpha_{n} }} H^\star R_{n}^G \nonumber \\
    & = ({I} - \alpha_{n} B_1) {\check{x}}_{n} - \sqrt{\alpha_{n}} \tilde{\xi}_{n} + R_{n}^x, \label{eq:lem:check-twotime:x-update}
\end{align}
where $\tilde{\xi}_{n} := \xi_{n} - \kappa_{n} H^\star \psi_{n} = \xi_{n} - \frac{\beta_{n}}{\alpha_{n}} H^\star \psi_{n}$ and 
\begin{align}\label{eq:lem:check-twotime:Rx}
    \begin{split}
        R_{n}^x
        & = \underbrace{ \left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } - 1 \right) {\check{x}}_{n} }_{=: R_{n,1}^x} 
        + \underbrace{ (\alpha_{n} - \sqrt{ \alpha_{n} \alpha_{n-1} }) B_1 {\check{x}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) } }_{=: R_{n,2}^x} 
        + \underbrace{ \sqrt{\frac{ \alpha_{n-1} }{ \alpha_{n} } } \beta_{n} H^\star B_2 {\check{x}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) }}_{=: R_{n,3}^x} \\
        & \qquad 
        + \underbrace{ \sqrt{ \frac{\beta_{n-1}}{\alpha_{n}} } \beta_{n} H^\star B_3 {\check{y}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) } }_{=: R_{n,4}^x} 
        - \underbrace{ \frac{1}{ \sqrt{\alpha_{n}} } R_{n}^{\nabla H} }_{=: R_{n,5}^x} 
        - \underbrace{ \frac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} }_{=: R_{n,6}^x} 
        - \underbrace{ \sqrt{\alpha_{n}} R_{n}^F 
            \vphantom{\frac{\beta_{n}}{\sqrt{ \alpha_{n} } } } }_{=:R_{n,7}^x } 
        + \underbrace{ \frac{\beta_{n}}{\sqrt{ \alpha_{n} } } H^\star R_{n}^G }_{=:R_{n,8}^x}.
    \end{split}
\end{align}
By \eqref{eq:lem:check-twotime:sqrtalpha}, we have
$\| R_{n,1}^x \| + \| R_{n,2}^x \| = {\mathcal O}(\beta_{n}) \| {\check{x}}_{n} \| = {\mathcal O}(\beta_{n} \alpha_{n}^{-1/2} ) \| {\hat{x}}_{n} \| $.






By Assumption~\ref{assump:stepsize-twotime}, we have
$\| R_{n,3}^x \| + \| R_{n,4}^x \| = {\mathcal O}(\beta_{n}) \| {\check{x}}_{n} \| + {\mathcal O} ( \beta_{n}^{3/2} \alpha_{n}^{-1/2} ) \| {\check{y}}_{n} \|
= {\mathcal O}(\beta_{n} \alpha_{n}^{-1/2} ) ( \| {\hat{x}}_{n} \| + \| {\hat{y}}_{n} \| ) $.
For $R_{n,5}^x$ and $R_{n,6}^x$,
from the definition of ${\mathcal F}_{n}$, Assumption~\ref{assump:smooth} and Proposition~\ref{prop:operator-decom}, we have
\begin{align*}
    \| {\mathbb E} [ R_{n}^{\nabla H} | {\mathcal F}_{n} ] \| 
    & = \| (\nabla H ({y}_{n}) - \nabla H ({y}^\star)) {\mathbb E}[ {y}_{n+1} - {y}_{n} | {\mathcal F}_{n} ] \| \\
    & = \beta_{n} \| (\nabla H ({y}_{n}) - \nabla H ({y}^\star)) G({x}_{n}, {y}_{n}) \| 
    \le \beta_{n} {\widetilde{S}_H} \|  {\hat{y}}_{n} \|^{\delta_H} \| G({x}_{n}, {y}_{n}) \| \\
    \| R_{n}^{\nabla H} \| 
    & \le {\widetilde{S}_H} \| {\hat{y}}_{n} \|^{{\delta_H}}  \| {y}_{n+1} - {y}_{n} \|  , \\
    \| R_{n}^H \| 
    & = {\mathcal O} ( \| {y}_{n+1} - {y}_{n} \|^{1+{\delta_H}} ), \\
    \| G({x}_{n}, {y}_{n}) \|
    & = \|  G({x}_{n}, {y}_{n}) - G( H({y}_{n}), {y}_{n} ) + G( H({y}_{n}), {y}_{n} ) - G( H({y}^\star), {y}^\star ) \| \\
    & \le  {L}_{G,x} \| {\hat{x}}_{n} \| +  {L}_{G,y} \| {\hat{y}}_{n} \|, \\
    \| {y}_{n+1} - {y}_{n} \| 
    & \le \beta_{n} \| G({x}_{n}, {y}_{n}) \| + \beta_{n} \| \psi_{n} \|.


\end{align*}
Then by Young's inequality and Jensen's inequality, we have
\begin{align*}
    \| {\mathbb E}[  R_{n,5}^x  | {\mathcal F}_n ] \| & = {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} ), \\
    \| R_{n,5}^x \| 
    & = {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{\delta_H} \| \psi_{n} \| ), \\
    \| R_{n,6}^x \| 
    & = {\mathcal O} (\beta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} + \| \psi_{n} \|^{1+{\delta_H}}  ).





\end{align*}
Moreover, Proposition~\ref{prop:operator-decom} also implies $\| R_{n,7}^x \| 
= {\mathcal O}(\alpha_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_F}} + \| {\hat{y}}_{n} \|^{1+{\delta_F}} )$ and 
$ \| R_{n,8}^x \| 
= {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ) $.
Summarizing the above results, we obtain
\begin{align}\label{eq:lem:check-twotime:Rx-upper}
    \begin{split}
        \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \|
        & = {\mathcal O}( \beta_{n} \alpha_{n}^{-1/2})  (\| {\hat{x}}_{n} \| + \| {\hat{y}}_{n} \| ) + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} ) \\
        & \quad \ + {\mathcal O} (\beta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2}) \| \psi_{n} \|^{1+{\delta_H}} + {\mathcal O}(\alpha_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_F}} + \| {\hat{y}}_{n} \|^{1+{\delta_F}} ) \\
        & \quad \ + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ), \\
        \| R_{n}^x \| 
        & = {\mathcal O}( \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| ) + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) \| {\hat{y}}_{n} \|^{\delta_H} \| \psi_{n} \|.
    \end{split}
\end{align}
Note that Assumption~\ref{assump:stepsize-twotime} requires $\alpha_{n}^{1+{\delta_F}} = o (\beta_{n})$, $\beta_{n}^{(1+{\delta_H}) / 2 } = {\mathcal O}(\alpha_{n})$.
By Assumption~\ref{assump:mart-decouple-rate}, we have
$ {\mathbb E} \|  {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| = {\mathcal O}( \beta_{n} + \beta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2} + \alpha_{n}^{1 + {\delta_F}/2}) = o(\sqrt{\beta_{n} \alpha_{n}}) $.
Meanwhile, since ${\hat{y}}_{n} \in {\mathcal F}_{n}$, Assumption~\ref{assump:noise-fclt} implies ${\mathbb E} \| {\hat{y}}_{n} \|^{2{\delta_H}} \| \psi_{n} \|^2 = {\mathcal O}( {\mathbb E} \| {\hat{y}}_{n} \|^{2{\delta_H}})$.
By Assumption~\ref{assump:mart-decouple-rate}, we have
$ {\mathbb E} \| R_{n}^x \|^2 = {\mathcal O}( \beta_{n}^2 + \beta_{n}^{2+{\delta_H}} \alpha_{n}^{-1} + \alpha_{n}^{2 + {\delta_F}}) = {\mathcal O}(\beta_n \alpha_n) $.
Moreover, by Propositions~\ref{prop:H-reduce-order} and \ref{prop:FG-reduce-order}, we have that \eqref{eq:lem:check-twotime:Rx-upper} holds after replacing ${\delta_H}, {\delta_F}, {\delta_G}$ with ${\delta_H}/2, {\delta_F}/2, {\delta_G}/2$ respectively.
For $2 \le p \le \frac{4}{1 + ({\delta_H} \vee {\delta_F} \vee {\delta_G}) / 2 }$, one can check ${\mathbb E} \| R_{n}^x \|^p = o(\alpha_{n}) $.
