    {\check{x}}_{n+1}
    & = \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } ({I} - \alpha_{n} B_1 + \beta_n H^\star B_2) {\check{x}}_{n} + \sqrt{ \frac{\beta_{n-1}}{\alpha_{n}} } \beta_{n} H^\star B_3 {\check{y}}_{n} - \sqrt{ \alpha_{n} } \xi_{n} + \frac{ \beta_{n} }{ \sqrt{ \alpha_{n} } } H^\star \psi_{n} \nonumber \\
    & \qquad - \frac{1}{ \sqrt{\alpha_{n}} } R_{n}^{\nabla H} - \frac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} - \sqrt{\alpha_{n}} R_{n}^F + \frac{\beta_{n}}{\sqrt{ \alpha_{n} }} H^\star R_{n}^G \nonumber \\
    & = ({I} - \alpha_{n} B_1) {\check{x}}_{n} - \sqrt{\alpha_{n}} \tilde{\xi}_{n} + R_{n}^x, \label{eq:lem:check-twotime:x-update}
\end{align}

\begin{align}\label{eq:lem:check-twotime:Rx}
    \begin{split}
        R_{n}^x
        & = \underbrace{ \left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } - 1 \right) {\check{x}}_{n} }_{=: R_{n,1}^x} 
        + \underbrace{ (\alpha_{n} - \sqrt{ \alpha_{n} \alpha_{n-1} }) B_1 {\check{x}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) } }_{=: R_{n,2}^x} 
        + \underbrace{ \sqrt{\frac{ \alpha_{n-1} }{ \alpha_{n} } } \beta_{n} H^\star B_2 {\check{x}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) }}_{=: R_{n,3}^x} \\
        & \qquad 
        + \underbrace{ \sqrt{ \frac{\beta_{n-1}}{\alpha_{n}} } \beta_{n} H^\star B_3 {\check{y}}_{n} 
            \vphantom{\left( \sqrt{ \frac{\alpha_{n-1}}{\alpha_{n}} } \right) } }_{=: R_{n,4}^x} 
        - \underbrace{ \frac{1}{ \sqrt{\alpha_{n}} } R_{n}^{\nabla H} }_{=: R_{n,5}^x} 
        - \underbrace{ \frac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} }_{=: R_{n,6}^x} 
        - \underbrace{ \sqrt{\alpha_{n}} R_{n}^F 
            \vphantom{\frac{\beta_{n}}{\sqrt{ \alpha_{n} } } } }_{=:R_{n,7}^x } 
        + \underbrace{ \frac{\beta_{n}}{\sqrt{ \alpha_{n} } } H^\star R_{n}^G }_{=:R_{n,8}^x}.
    \end{split}
\end{align}

\begin{align}\label{eq:lem:check-twotime:Rx-upper}
    \begin{split}
        \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \|
        & = {\mathcal O}( \beta_{n} \alpha_{n}^{-1/2})  (\| {\hat{x}}_{n} \| + \| {\hat{y}}_{n} \| ) + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} ) \\
        & \quad \ + {\mathcal O} (\beta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2}) \| \psi_{n} \|^{1+{\delta_H}} + {\mathcal O}(\alpha_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_F}} + \| {\hat{y}}_{n} \|^{1+{\delta_F}} ) \\
        & \quad \ + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ), \\
        \| R_{n}^x \| 
        & = {\mathcal O}( \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| ) + {\mathcal O} (\beta_{n} \alpha_{n}^{-1/2}) \| {\hat{y}}_{n} \|^{\delta_H} \| \psi_{n} \|.
    \end{split}
\end{align}

\begin{align*}
    {\check{z}}_{n+1}
    & = {\check{y}}_{n+1} - \sqrt{\kappa_{n}} B_2 B_1^{-1} {\check{x}}_{n+1} \\
    & = \left( {I} - \beta_{n} B_3 + \frac{\tilde{\beta} \beta_{n}}{2} {I} \right) ({\check{z}}_{n} + \sqrt{\kappa_{n-1}} B_2 B_1^{-1} {\check{x}}_{n})

    - \sqrt{ \beta_{n} \alpha_{n} } B_2 {\check{x}}_{n} - \sqrt{ \beta_{n} } \psi_{n} + R_{n}^y \\
    & \quad - \sqrt{\kappa_{n}} B_2 B_1^{-1} \left[ ({I} - \alpha_{n} B_1 ) {\check{x}}_{n} - \sqrt{\alpha_{n}} \tilde{\xi}_{n} + R_{n}^x \right] \\
    & = \left( {I} - \beta_{n} B_3 + \frac{\tilde{\beta} \beta_{n}}{2} {I} \right) {\check{z}}_{n} - \sqrt{\beta_{n}} \tilde{\psi}_{n} + R_{n}^z,
\end{align*}

\begin{align*}
    R_{n}^z
    & = \underbrace{ (\sqrt{\kappa_{n-1}} {-} \sqrt{\kappa_{n}}) B_2 B_1^{-1} {\check{x}}_{n} }_{=: R_{n,1}^z} 
    - \underbrace{ \sqrt{\kappa_{n-1}} \beta_{n} (B_3 {-} \tilde{\beta} {I} / 2) B_2 B_1^{-1} {\check{x}}_{n} }_{=: R_{n,2}^z}

    + R_{n}^{y} - \sqrt{\kappa_{n}} B_2 B_1^{-1} R_{n}^x.
\end{align*}

We begin by proving the tightness of $\{ {\bar{\textnormal{X}}}_{n}(\cdot) \}_{n=1}^\infty$. The tightness of $\{ {\bar{\textnormal{Z}}}_{n}(\cdot) \}_{n=1}^\infty$ can be established using a similar approach. Finally, we address the tightness of $\{ {\bar{\textnormal{Y}}}_{n}(\cdot) \}_{n=1}^\infty$, which is the primary challenge in this proof.
\vspace{0.2cm}

\textbf{Part~1: tightness of $\{ {\bar{\textnormal{X}}}_{n}(\cdot) \}_{n=1}^\infty$}.


Note that Assumption~\ref{assump:mart-decouple-rate} implies ${\mathbb E} \| {\bar{\textnormal{X}}}_{n}(0) \|^2 = {\mathbb E} \| {\check{x}}_{n} \|^2 = {\mathcal O}(1)$. 
Then by Markov's inequality, the first condition in Proposition~\ref{prop:tight-suff-slow} holds.
Now we verify the second condition.
Without loss of generality,  assume $0 \le t < s \le T$.
From the definition of ${\bar{\textnormal{X}}}_{n}(t)$ in \eqref{eq:def:xbar}, we have
\begin{align*}
    {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}(t)
    & \overset{\eqref{eq:def:xbar}}{=} {\check{x}}_{N^\alpha(n,s)} + (s - \underline{s}^\alpha_{n} ) \left( - B_1 {\check{x}}_{N^\alpha(n,s)} + \frac{ R_{N^\alpha(n,s)}^x }{ \alpha_{N^\alpha(n,s)} } \right) - \frac{s - \underline{s}^\alpha_{n}}{ \sqrt{ \alpha_{N^\alpha(n,s)} } } 

    \tilde{\xi}_{N^\alpha(n,s)} \\
    & \qquad - {\check{x}}_{N^\alpha(n,t)} - (t - \underline{t}^\alpha_{n} ) \left( - B_1 {\check{x}}_{N^\alpha(n,t)} + \frac{ R_{N^\alpha(n,t)}^x }{ \alpha_{N^\alpha(n,t)} } \right) + \frac{t - \underline{t}^\alpha_{n}}{ \sqrt{\alpha_{N^\alpha(n,t)} } } 

    \tilde{\xi}_{N^\alpha(n,t)} \\
    & \overset{\eqref{eq:xcheck-twotime}}{=} \Bigg\{ \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)-1} \alpha_{k} \left( - B_1 {\check{x}}_{k} + \frac{R_{k}^x}{\alpha_{k}} \right) - (t - \underline{t}^\alpha_{n} ) \left( - B_1 {\check{x}}_{N^\alpha(n,t)} + \frac{ R_{N^\alpha(n,t)}^x }{ \alpha_{N^\alpha(n,t)} } \right) \\
    & \qquad + (s - \underline{s}^\alpha_{n} ) \left( - B_1 {\check{x}}_{N^\alpha(n,s)} + \frac{ R_{N^\alpha(n,s)}^x }{ \alpha_{N^\alpha(n,s)} } \right) \Bigg\} - \Bigg\{ \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)-1} \sqrt{\alpha_{k}} \tilde{\xi}_{k} \\ 
    & \qquad -  \frac{t - \underline{t}^\alpha_{n}}{ \sqrt{\alpha_{N^\alpha(n,t)} } } 

    \tilde{\xi}_{N^\alpha(n,t)} 
    + \frac{s - \underline{s}^\alpha_{n}}{ \sqrt{ \alpha_{N^\alpha(n,s)} } } 

    \tilde{\xi}_{N^\alpha(n,s)} \Bigg\} \\
    & =: {\bf B}^{(1x,n)}_{t,s} - \mbox{\boldmath$\Xi$\unboldmath}^{(n)}_{t,s}.
\end{align*}

For the first term, 

noting that $t' - (\underline{t'})^\alpha_{n} \le \alpha_{N^\alpha(n,t')}$ for $t'=t,s$,
we have
\begin{align}
    \| {\bf B}^{(1x,n)}_{t,s} \| & \le \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s) - 1} \alpha_{k} \left\| B_1 {\check{x}}_{k} - \frac{R_{k}^x}{\alpha_{k}} \right\| + (s - \underline{s}^\alpha_{n}) \left\| B_1 {\check{x}}_{N^\alpha(n,s)} - \frac{ R_{N^\alpha(n,s)}^x }{ \alpha_{N^\alpha(n,s)} } \right\| \nonumber \\
    & \le \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)} \alpha_{k} \left\| B_1 {\check{x}}_{k} - \frac{R_{k}^x}{\alpha_{k}} \right\|. \label{eq:lem:tight-twotime:B1x-1}
\end{align}
By Assumption~\ref{assump:mart-decouple-rate} and Lemma~\ref{lem:check-twotime-xy}, we have that 
\begin{align}
    \label{eq:lem:tight-twotime:l2bound-x}
    \sup_{n} {\mathbb E} \left\| B_1 {\check{x}}_{n} - \frac{R_{n}^x }{ \alpha_{n}} \right\|^2 \le 2 \| B_1 \|^2 \sup_{n} {\mathbb E} \| {\check{x}}_{n} \|^2 + 2 \sup_{n} \frac{ {\mathbb E} \| R_{n}^x \|^2}{\alpha_{n}^2} \le C^{ti}_x
\end{align}

for some $C^{ti}_x > 0$. 
Applying the Cauchy-Schwarz inequality, we obtain
\begin{align}
    {\mathbb E} \| {\bf B}^{(1x,n)}_{t,s} \|^2
    & \overset{\eqref{eq:lem:tight-twotime:B1x-1}}{\le}
    {\mathbb E} \left( \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)} \alpha_{k} \left\| B_1 {\check{x}}_{k} - \frac{R_{k}^x}{\alpha_{k}} \right\|\right)^2 \nonumber \\
    & \le \left( \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)} \alpha_{k} \right) \left( \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)} \alpha_{k} {\mathbb E}  \left\| B_1 {\check{x}}_{k} - \frac{R_{k}^x}{\alpha_{k}} \right\|^2 \right) \nonumber \\
    & \overset{ \eqref{eq:lem:tight-twotime:l2bound-x} }{\le} C^{ti}_x \left( \ssum{k}{N^\alpha(n,t)}{N^\alpha(n,s)} \alpha_{k} \right)^2 
    \le  C^{ti}_x ( s-t + 2 \alpha_{n} )^2
    \overset{(a)}{\le} K_1(s-t)^2,
    \label{eq:lem:tight-twotime:B1x}

\end{align}
where there exists $K_1$ such that (a) holds for any $n$ because $\alpha_{n} \to 0$.

For the second term, 
with $p \in \left(2, \frac{4}{1 + ( {\delta_H} \vee {\delta_F} \vee {\delta_G} )/2} \right]$,

we have
\begin{align*}
    {\mathbb E} \| \mbox{\boldmath$\Xi$\unboldmath}^{(n)}_{t,s} \|^p
    & \overset{\eqref{eq:burk-jensen}}{\le}  C^{ti}_p \left[ N^\alpha(n, s) - N^\alpha(n,t) + 1 \right]^{\frac{p}{2}-1} \ssum{k}{ N^\alpha(n,t) }{N^\alpha(n,s) } \alpha_{k}^\frac{p}{2} {\mathbb E} \| \tilde{\xi}_{k} \|^p,
\end{align*}
where we have used $t' - \underline{t'}^\alpha_{n} \le \alpha_{N^\alpha(n,t')}$ for $t'=t,s$ and Burkholder's inequality in the following proposition with $C^{ti}_p = \left[ (p-1) \vee \frac{1}{p-1} \right]^p$.

\begin{prop}[Burkholder's inequality, {\cite{burkholder1988sharp}}]\label{prop:burk}
    Fix any $p \ge 2$.
    Let $\{ X_k \}_{1 \le k \le n}$ be a finite ${\mathbb R}^d$-valued martingale difference sequence with $\sup_{1 \le k \le n} {\mathbb E} \| X_k \|^p < \infty$. Then we have
    \begin{align*}
        {\mathbb E} \left\| \ssum{k}{1}{n} X_k \right\|^p \le \left[ (p-1) \vee \frac{1}{p-1} \right]^p {\mathbb E} \left( \ssum{k}{1}{n} \| X_k \|^2 \right)^\frac{p}{2},
    \end{align*}
    which together with Jensen's inequality imply 
    \begin{align}\label{eq:burk-jensen}
        {\mathbb E} \left\| \ssum{k}{1}{n} X_k \right\|^p \le \left[ (p-1) \vee \frac{1}{p-1} \right]^p n^{\frac{p}{2} - 1 } {\mathbb E} \ssum{k}{1}{n} \| X_k \|^p.
    \end{align}
\end{prop}

From the definition of $\tilde{\xi}_{k}$ and Assumption~\ref{assump:noise-fclt}, there exists $C^{ti}_\xi > 0$ such that $\sup_{k} {\mathbb E} \| \tilde{\xi}_{k} \|^p \le C^{ti}_\xi $.
It follows that
\begin{align}
    {\mathbb E} \| \mbox{\boldmath$\Xi$\unboldmath}^{(n)}_{t,s} \|^p
    & \le C^{ti}_p C^{ti}_\xi \left( \frac{ s-t + 2\alpha_{n} }{ \alpha_{ N^\alpha(n, s) } }  + 1 \right)^{\frac{p}{2}-1}  \alpha_{n}^{ \frac{p}{2} - 1 } \ssum{k}{ N^\alpha(n,t) }{N^\alpha(n,s) } \alpha_{k} \nonumber \\

    & \le  C^{ti}_p C^{ti}_\xi ( s-t + 3 \alpha_{n} )^\frac{p}{2} \left( \frac{ \alpha_{n} }{ \alpha_{ N^\alpha(n, s) }  } \right)^{\frac{p}{2}-1 } \nonumber \\
    & \overset{ (a) }{\le} C^{ti}_p C^{ti}_\xi C^{ti}_\alpha ( s-t + 3 \alpha_{n} )^\frac{p}{2}
    \overset{ (b) }{\le} K_2 ( s-t )^\frac{p}{2},

    \label{eq:lem:tight-twotime:xii}
\end{align}
where (a) uses Lemma~\ref{lem:aux:bounded} with $C^{ti}_\alpha = 2^{ ( \lceil 2T/ c_\alpha \rceil + 1 )(p/2-1) }$ with $c_\alpha$ specified therein, 
and there exists $K_2$ such that (b) holds for any $n$.


Combining \eqref{eq:lem:tight-twotime:B1x} and \eqref{eq:lem:tight-twotime:xii} with Markov's inequality, 
we have
\begin{align*}
    {\mathbb P} \left( 

    \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}(t) \| \ge {\varepsilon} \right)
    & \le {\mathbb P} \left( 

    \| {\bf B}^{(1x,n)}_{t,s} \| \ge \frac{{\varepsilon}}{2} \right) + {\mathbb P} \left( 

    \| \mbox{\boldmath$\Xi$\unboldmath}^{(n)}_{t,s} \| \ge \frac{{\varepsilon}}{2} \right) 
    \\
    & \le \frac{4}{{\varepsilon}^2} {\mathbb E} \| {\bf B}^{(1x,n)}_{t,s} \| ^2 + \frac{2^p}{{\varepsilon}^p} {\mathbb E} \| \mbox{\boldmath$\Xi$\unboldmath}^{(n)}_{t,s} \|^p \\
    & 
    \le 8 (K_1 \vee K_2) \left[ \frac{ (s-t)^2 }{{\varepsilon}^2} + \frac{ (s-t)^\frac{p}{2} }{{\varepsilon}^p} \right].

\end{align*}
This upper bound verifies the second condition in Proposition~\ref{prop:tight-suff-slow}. Consequently, $\{ {\bar{\textnormal{X}}}_{n}(\cdot) \}_{n=1}^\infty$ is tight.
\vspace{0.2cm}

\textbf{Part~2: the tightness of $\{ {\bar{\textnormal{Z}}}_{n}(\cdot) \}_{n=1}^\infty$}.
Note that in the proof of Part~1, the only place we employed Lemma~\ref{lem:check-twotime-xy} is \eqref{eq:lem:tight-twotime:l2bound-x} and in fact, we only require ${\mathbb E} \| R_{n}^x \|^2 = {\mathcal O}(\alpha_{n}^2)$. Moreover, the dimension $d_x$ would not affect the proof.
The tightness of $\{ {\bar{\textnormal{Z}}}_{n}(\cdot) \}_{n=1}^\infty$ follows from a similar procedure by applying the residual bounds in Lemma~\ref{lem:check-twotime-z}.
\vspace{0.2cm}

\textbf{Part~3: the tightness of $\{ {\bar{\textnormal{Y}}}_{n}(\cdot) \}_{n=1}^\infty$}.
Note that Assumption~\ref{assump:mart-decouple-rate} implies ${\mathbb E} \| {\bar{\textnormal{Y}}}_{n}(0) \|^2 = {\mathbb E} \| {\check{y}}_{n} \|^2 = {\mathcal O}(1)$. 
Then by Markov's inequality, the first condition in Proposition~\ref{prop:tight-suff-slow} holds.
Now we verify the second condition.
Without loss of generality, we assume $0 \le t < s \le T$.
For ease of notation, we define $\widetilde{B}_3 := B_3 - \frac{\tilde{\beta} {I}}{2}$.
From the definition of ${\bar{\textnormal{Y}}}_{n}(t)$ in \eqref{eq:def:ybar}, we have

\begin{align*}
    {\bar{\textnormal{Y}}}_{n}(s) - {\bar{\textnormal{Y}}}_{n}(t)
    & \overset{\eqref{eq:def:ybar}}{=} {\check{y}}_{N^\beta(n,s)} + (s - \underline{s}^\beta_{n} ) \left( - \widetilde{B}_3  {\check{y}}_{N^\beta(n,s)} + \frac{ R_{N^\beta(n,s)}^y }{ \beta_{N^\beta(n,s)} } \right) -  \frac{s - \underline{s}^\beta_{n}}{ \sqrt{ \beta_{N^\beta(n,s) } } }  

    \psi_{N^\beta(n,s)} \\
    & \qquad - {\check{y}}_{N^\beta(n,t)} - (t - \underline{t}^\beta_{n} ) \left( - \widetilde{B}_3 {\check{y}}_{N^\beta(n,t)} + \frac{ R_{N^\beta(n,t)}^y }{ \beta_{N^\beta(n,t)} } \right) +  \frac{t - \underline{t}^\beta_{n}}{ \sqrt{ \beta_{N^\beta(n,t)} } }

    \psi_{N^\beta(n,t)} \\
    & \qquad - (s - \underline{s}^\beta_{n}) \sqrt{ \frac{ \alpha_{N^\beta(n,s)} }{ \beta_{N^\beta(n,s)} } } B_2 {\check{x}}_{N^\beta(n,s)} 
    + (t - \underline{t}^\beta_{n}) \sqrt{ \frac{ \alpha_{N^\beta(n,t)} }{ \beta_{N^\beta(n,t)} } } B_2 {\check{x}}_{N^\beta(n,t)} \\
    & \overset{\eqref{eq:ycheck-twotime}}{=} \Bigg\{ \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \beta_{k} \left( - \widetilde{B}_3 {\check{y}}_{k} + \frac{R_{k}^y}{\beta_{k}} \right) - (t - \underline{t}^\beta_{n} ) \left( - \widetilde{B}_3 {\check{y}}_{N^\beta(n,t)} + \frac{ R_{N^\beta(n,t)}^y }{ \beta_{N^\beta(n,t)} } \right) \\  
    & \qquad+ (s - \underline{s}^\beta_{n} ) \left( - \widetilde{B}_3 {\check{y}}_{N^\beta(n,s)} + \frac{ R_{N^\beta(n,s)}^y }{ \beta_{N^\beta(n,s)} } \right) \Bigg\}  - \Bigg\{ \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \sqrt{\beta_{k}} \psi_{k} \\
    & \qquad -  \frac{t - \underline{t}^\beta_{n}}{ \sqrt{\beta_{N^\beta(n,t)} } } \psi_{N^\beta(n,t)} 
    + \frac{s - \underline{s}^\beta_{n}}{ \sqrt{\beta_{N^\beta(n,s)} } } \psi_{N^\beta(n,s)} \Bigg\}
    - \Bigg\{ \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \beta_{k} \sqrt{ \frac{\alpha_{k}}{\beta_{k}} } B_2 {\check{x}}_{k} \\
    & \qquad  - (t - \underline{t}^\beta_{n}) \sqrt{ \frac{ \alpha_{N^\beta(n,t)} }{ \beta_{N^\beta(n,t)} } } B_2 {\check{x}}_{N^\beta(n,t)} + (s - \underline{s}^\beta_{n}) \sqrt{ \frac{ \alpha_{N^\beta(n,s)} }{ \beta_{N^\beta(n,s)} } } B_2 {\check{x}}_{N^\beta(n,s)} 
    \Bigg\} \\
    & =: {\bf B}^{(3y,n)}_{t,s} - \mbox{\boldmath$\Psi$\unboldmath}^{(n)}_{t,s} - {\bf B}^{(2x,n)}_{t,s}.
\end{align*}


For the first and second terms,
similar to the derivation of \eqref{eq:lem:tight-twotime:B1x} and \eqref{eq:lem:tight-twotime:xii}, with $p \in \left(2, \frac{4}{1 + ( {\delta_H} \vee {\delta_F} \vee {\delta_G} )/2} \right]$, there exist $K_3, K_4$ such that for any $n$,
\begin{align}\label{eq:lem:tight-slow:BandPsi}
    {\mathbb E} \| {\bf B}^{(3y,n)}_{t,s} \|^2 \le K_3 (s-t)^2 \quad \text{ and } \quad
    {\mathbb E} \| \mbox{\boldmath$\Psi$\unboldmath}^{(n)}_{t,s} \|^p \le K_4 (s-t)^\frac{p}{2}.
\end{align}

\textbf{Main difficulty}.
The main difficulty lies to how to deal with the last term $ {\bf B}^{(2x,n)}_{t,s}$.
If we adopt a similar procedure of deriving \eqref{eq:lem:tight-twotime:B1x} by the Cauchy-Schwarz inequality,
we could only obtain 
\[{\mathbb E} \| {\bf B}^{(2x,n)}_{t,s} \|^2 \lesssim (s-t)  \left( \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)} \beta_{k} \frac{\alpha_{k} }{\beta_{k}} \right)
\lesssim (s-t)^2 \max_{k \ge N^\beta(n,s)} \frac{\alpha_{k}}{\beta_{k}}.
\] 
Since Assumption~\ref{assump:stepsize-twotime}~\ref{assump:stepsize-twotime-tozero} implies $\max_{k \ge N^\beta(n,s)} \alpha_{k} / \beta_{k} \to \infty$ as $n \to \infty$, this upper bound becomes ineffective.
\vspace{0.2cm}

\textbf{Solution approach}.
To address this issue, we need to provide a more precise characterization of $ {\bf B}^{(2x,n)}_{t,s}$.
A natural approach is to further expand each ${\check{x}}_{k}$. While this idea is feasible, it leads to more complex calculations, as each ${\check{x}}_{k}$ depends on both ${\check{x}}_{k-1}$ and ${\check{y}}_{k-1}$. Below, we outline the detailed process.

To begin, we define another term 

    ${\bf B}^{(2x)}_{n_0,n_1}
    := \ssum{k}{n_0}{n_1} \sqrt{\beta_{k}} B_2 {\hat{x}}_{k}$.
    Here, we use the unrescaled iterate to simplify the subsequent calculations. Given that ${\check{x}}_{k} = {\hat{x}}_{k} / \sqrt{\alpha_{k-1} }$, it follows that
    ${\bf B}^{(2x)}_{n_0,n_1} = \ssum{k}{n_0}{n_1} \sqrt{ \beta_{k} \alpha_{k-1} } B_2 {\check{x}}_{k}
    $, which demonstrates that this term is closely related to ${\bf B}^{(2x,n)}_{t,s}$, as shown in the following equation
    \begin{align*}
        {\bf B}^{(2x,n)}_{t,s} 
        & = {\bf B}^{(2x)}_{N^\beta(n,t), N^\beta(n,s)-1}
        - (t - \underline{t}^\beta_{n}) \sqrt{ \frac{ \alpha_{N^\beta(n,t)} }{ \beta_{N^\beta(n,t)} } } B_2 {\check{x}}_{N^\beta(n,t)} \\
        & \qquad  + (s - \underline{s}^\beta_{n})

        \sqrt{ \frac{ \alpha_{N^\beta(n,s)} }{ \beta_{N^\beta(n,s)} } } B_2 {\check{x}}_{N^\beta(n,s)} 
        + \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \sqrt{\beta_{k}} \left( \sqrt{ \frac{\alpha_{k}}{\alpha_{k-1}} } - 1 \right) B_2 {\hat{x}}_{k}.
    \end{align*}
    By the Cauchy-Schwarz inequality, we have
    \begin{align*}
        & {\mathbb E} \left\| \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \sqrt{\beta_{k}} \left( \sqrt{ \frac{\alpha_{k}}{\alpha_{k-1}} } - 1 \right) B_2 {\hat{x}}_{k} \right\|^2 \\
        & \qquad \qquad \le \left( \ssum{k}{N^\beta(n,t)}{N^\beta(n,s)-1} \beta_{k} \right) \left[ \ssum{k}  {N^\beta(n,t)}{N^\beta(n,s)-1}  \Big( \sqrt{ \frac{\alpha_{k}}{\alpha_{k-1}} } - 1 \Big)^2  {\mathbb E} \| B_2 {\hat{x}}_{k} \|^2 \right].
    \end{align*}
    In \eqref{eq:lem:check-twotime:sqrtalpha}, we have shown that $\sqrt{ \frac{\alpha_{k}}{\alpha_{k-1}} } - 1 = o(\beta_k)$.
    Assumption~\ref{assump:mart-decouple-rate} implies ${\mathbb E} \| B_2 {\hat{x}}_{k} \|^2 = o(1)$.
    Moreover,
    $t' - (\underline{t'})^\beta_{n} \le \beta_{N^\beta(n,t')}$ for $t'=t,s$.

    Summarizing the above results and following a similar procedure as \eqref{eq:lem:tight-twotime:B1x}, we can obtain that there exists $K_5$ such that
    \begin{align}\label{eq:lem:tight-slow:Bdiff}
        {\mathbb E} \| {\bf B}^{(2x,n)}_{t,s} - {\bf B}^{(2x)}_{N^\beta(n,t), N^\beta(n,s)-1} \|^2
        \le K_5 (s-t)^2
    \end{align}
    for any $n$.
    This inequality controls the difference between ${\bf B}^{(2x,n)}_{t,s}$ and 
    ${\bf B}^{(2x)}_{N^\beta(n,t), N^\beta(n,s)-1}$.

    \vspace{0.2cm}



    From now on, we always assume $n_0 = N^\beta(n,t)$ and $n_1 = N^\beta(n,s)-1$ and
    It remains to deal with the term ${\bf B}^{(2x)}_{n_0, n_1}$.
    Recall that the update rule of ${\hat{x}}_{n}$ is shown in \eqref{eq:xhat-decom}.
    For ease of notation, we define $A_{n}:= {I} - \alpha_{n} B_1 + \beta_{n} H^\star B_2$, $\tilde{\xi}_{n} := \xi_{n} - \beta_{n} H^\star \psi_{n} / \alpha_{n}$ and 
    $\tilde{R}^x_{n} := R^{\nabla H}_{n} + R^H_{n} + \alpha_{n} R^F_{n} - \beta_{n} H^\star R^G_{n}$.
    Then the update rule of ${\hat{x}}_{n}$ can be rewritten as
    \begin{align*}
        {\hat{x}}_{n+1} = A_{n} {\hat{x}}_{n} + \beta_{n} H^\star B_3 {\hat{y}}_{n} - \alpha_{n} \tilde{\xi}_{n} - \tilde{R}^x_{n}.
    \end{align*}
    Applying this equation multiple times yields
    \begin{align*}
        {\hat{x}}_{n+m}
        = \bigg( \prod_{i=1}^{m} A_{n+m-i} \bigg) {\hat{x}}_{n}
        + \sum_{l=n}^{n+m-1} \bigg( \prod_{i=1}^{n+m-l-1} A_{n+m-i} \bigg) \big( \beta_{l} H^\star B_3 {\hat{y}}_{l} - \alpha_{l} \tilde{\xi}_{l} - \tilde{R}^x_{l} \big).
    \end{align*}
    It follows that
    \begin{align*}
        {\bf B}^{(2x)}_{n_0, n_1}

        & = \ssum{k}{n_0}{n_1} \sqrt{\beta_{k}} B_2 \left[ \bigg( \prod_{i=1}^{k-n_{0}} A_{k-i} \bigg) {\hat{x}}_{n_0} + \ssum{l}{n_0}{k-1} \bigg( \prod_{i=1}^{k-l-1} A_{k-i} \bigg) \big( \beta_{l} H^\star B_3 {\hat{y}}_{l} - \alpha_{l} \tilde{\xi}_{l} - \tilde{R}^x_{l} \big) \right] \\
        & = \ssum{k}{n_0}{n_1} \sqrt{\beta_{k}} B_2 \bigg( \prod_{i=1}^{k-n_{0}} A_{k-i} \bigg) {\hat{x}}_{n_0} 
        + \ssum{l}{n_0}{n_1-1} \ssum{k}{l+1}{n_1} \sqrt{\beta_{k}} B_2 \bigg( \prod_{i=1}^{k-l-1} A_{k-i} \bigg) \big( \beta_{l} H^\star B_3 {\hat{y}}_{l} {-} \alpha_{l} \tilde{\xi}_{l} {-} \tilde{R}^x_{l} \big) \\
        & = \underbrace{ B_2 \widetilde{\Gamma}_{n_0, n_1} {\hat{x}}_{n_0} 
            + B_2 \ssum{l}{n_0}{n_1-1} \widetilde{\Gamma}_{l+1, n_1} \big( \beta_{l} H^\star B_3 {\hat{y}}_{l}  - \tilde{R}^x_{l} \big) }_{:= {\bf B}^{(2x,1)}_{n_0,n_1} }
        - \underbrace{ B_2 \ssum{l}{n_0}{n_1-1} \widetilde{\Gamma}_{l+1, n_1} \alpha_{l} \tilde{\xi}_{l} }_{:= {\bf B}^{(2x,2)}_{n_0,n_1} },
    \end{align*}
    where we define $\widetilde{\Gamma}_{m, j} := \ssum{k}{m}{j} \sqrt{\beta_{k}} \bigg( \prod_{i=1}^{k-m} A_{k-i} \bigg)$ in the last step.
    The magnitude of $\widetilde{\Gamma}_{m, j}$ can be controlled by the following auxiliary lemma, whose proof is deferred to the end of this subsection.

    \begin{lem}\label{lem:slow:stepsize-aux}
        Suppose that Assumption~\ref{assump:stepsize-twotime} holds and
        the real parts of the eigenvalues of $B_1$ are no less than $\mu_1$.
        Define $A_{k}:= {I} - \alpha_{k} B_1 + \beta_{k} H^\star B_2$.
        If $t$ and $s$ are fixed positive numbers satisfying $s>t$ and $n$ is sufficiently large,


        then for any $N^\beta(n,t) \le l < N^\beta(n, s)$, 

        we have
        \begin{align*}

            \left\| \sum_{k=l+1}^{N^\beta(n,s)-1} \sqrt{\beta_{k}} \prod_{i=1}^{k-l-1} A_{k-i}

            \right\|
            \le \frac{ 2^{ \left\lceil 2s/c_\alpha \right\rceil + 3} }{\mu_1} \cdot

            \frac{ \sqrt{\beta_{l}} }{ \alpha_{l} }.

        \end{align*}


    \end{lem}

    For the first term ${\bf B}^{(2x,1)}_{n_0,n_1}$, the Cauchy-Schwarz inequality implies
    \begin{align*}
        & \quad {\mathbb E} \| {\bf B}^{(2x,1)}_{n_0,n_1} \|^2 \\
        & \le 2  {\mathbb E} \| B_2 \widetilde{\Gamma}_{n_0, n_1} {\hat{x}}_{n_0} \|^2 + 2 {\mathbb E} \left\| B_2 \ssum{l}{n_0}{n_1-1} \widetilde{\Gamma}_{l+1, n_1} (\beta_{l} H^\star B_3 {\hat{y}}_{l} - \tilde{R}^x_{l} ) \right\|^2 \\
        & \le 2 (\| B_2 \| \|\widetilde{\Gamma}_{n_0, n_1} \|)^2 {\mathbb E} \| {\hat{x}}_{n_0} \|^2 + 2 \| B_2 \|^2 \left( \ssum{l}{n_0}{n_1-1} \beta_{l} \right) \!
        \left( \ssum{l}{n_0}{n_1-1} \beta_{l} \| \widetilde{\Gamma}_{l+1, n_1} \|^2  {\mathbb E} \left\| H^\star B_3 {\hat{y}}_{l} {-} \frac{\tilde{R}^x_{l}}{\beta_{l}}  \right\|^2

        \right).

    \end{align*}
    By Lemma~\ref{lem:slow:stepsize-aux}, 
    when $n$ is sufficiently large, we $\| \widetilde{\Gamma}_{l+1,n_1} \| \le \frac{ 2^{ \left\lceil 2T/c_\alpha \right\rceil + 3} }{\mu_1} \frac{ \sqrt{\beta_{l}} }{ \alpha_{l} } $ for any $n_0 \le l < n_1$ and $\| \widetilde{\Gamma}_{n_0, n_1} \| \le \frac{ 2^{ \left\lceil 2T/c_\alpha \right\rceil + 3} }{\mu_1} \frac{ \sqrt{\beta}_{n_0} }{ \alpha_{n_0} } + \sqrt{\beta_{n_0}} $, with $\mu_1$ and $c_\alpha$ specified in Lemma~\ref{lem:slow:stepsize-aux};
    Assumption~\ref{assump:mart-decouple-rate} implies ${\mathbb E} \| {\hat{x}}_{n_0} \|^2 = {\mathcal O}(\alpha_{n_0})$ and ${\mathbb E} \| {\hat{y}}_{l} \|^2 = {\mathcal O} (\beta_{l})$;
    the upper bounds in \eqref{eq:lem:check-twotime:Rx-upper} and the subsequent analysis therein imply that under Assumption~\ref{assump:stepsize-twotime},
    ${\mathbb E} \| \tilde{R}^x_{l} \|^2 = {\mathcal O}( \beta_{l}^2 \alpha_{l}^{1+{\delta_H}} + \beta_{l}^{2+{\delta_H}} + \alpha_{l}^{3+{\delta_F}} + \beta_{l}^2 \alpha_{l}^{1+{\delta_G}} ) = {\mathcal O}(\alpha_{l}^2 \beta_{l})$.
    Therefore, we have $\|\widetilde{\Gamma}_{n_0, n_1} \|^2 {\mathbb E} \| {\hat{x}}_{n_0} \|^2 = {\mathcal O} \left( \frac{\beta_{n_0} }{\alpha_{n_0}} \right) = o(1)$ and
    \begin{align*}


        \|\widetilde{\Gamma}_{l+1, n_1} \|^2 {\mathbb E} \left\| H^\star B_3 {\hat{y}}_{l} - \frac{ \tilde{R}^x_{l} }{\beta_{l}} \right\|^2
        & = {\mathcal O} \left( \frac{\beta_{l}}{\alpha_{l}^2} \right) \left( {\mathbb E} \| {\hat{y}}_{l} \|^2 + \frac{ {\mathbb E} \| \tilde{R}^x_{l} \|^2 }{ \beta_{l}^2 } \right) = {\mathcal O}(1).
    \end{align*}
    Then similar to the derive of \eqref{eq:lem:tight-twotime:B1x}, there exist  $K_6$ and $m_1$ such that
    \begin{align}\label{eq:lem:tight-slow:B2x-1}
        {\mathbb E} \| {\bf B}^{(2x,1)}_{n_0,n_1} \|^2 \le K_6 (s-t)^2
    \end{align}
    holds for any $n \ge m_1$.
    Modifying $K_6$, we could make \eqref{eq:lem:tight-slow:B2x-1} hold for any $n$.

    For the second term ${\bf B}^{(2x,2)}_{n_0,n_1}$,
    applying $\| \widetilde{\Gamma}_{l+1,n_1} \| \le C_T \frac{ \sqrt{\beta_{l}} }{ \alpha_{l} } $ with $C_T := \frac{ 2^{ \left\lceil 2T/c_\alpha \right\rceil + 3} }{\mu_1}$, we obtain that with $p \in \left(2, \frac{4}{1 + ( {\delta_H} \vee {\delta_F} \vee {\delta_G} )/2} \right]$ and sufficiently large $n$, 
    \begin{align*}
        {\mathbb E} \| {\bf B}^{(2x,2)}_{n_0,n_1} \|^p
        & \overset{\eqref{eq:burk-jensen}}{\le} C^{ti}_p \left( n_1 - n_0 \right)^{\frac{p}{2}-1} \| B_2 \|^p \ssum{l}{ n_0 }{n_1-1 } \| \widetilde{\Gamma}_{l+1, n_1} \|^p \alpha_{l}^p {\mathbb E} \| \tilde{\xi}_{l} \|^p

        \\
        & \le C^{ti}_p C_{T}^p \left( n_1 - n_0 \right)^{\frac{p}{2}-1} \| B_2 \|^p \ssum{l}{ n_0 }{n_1-1 } \beta_{l}^\frac{p}{2} {\mathbb E} \| \tilde{\xi}_{l} \|^p,
    \end{align*}
    where we have used Burkholder's inequality in  Proposition~\ref{prop:burk} with $C^{ti}_p = \left[ (p-1) \vee \frac{1}{p-1} \right]^p$.
    Then following a similar procedure to
    \eqref{eq:lem:tight-twotime:xii},
    we have that there exist $K_7$ and $m_2$ such that
    \begin{align}\label{eq:lem:tight-slow:B2x-2}
        {\mathbb E} \| {\bf B}^{(2x,2)}_{n_0,n_1} \|^p \le K_7 (s-t)^\frac{p}{2}
    \end{align}
    for any $n \ge m_2$. Modifying $K_7$, we could make \eqref{eq:lem:tight-slow:B2x-2} hold for any $n$.

    The upper bounds in \eqref{eq:lem:tight-slow:Bdiff}, \eqref{eq:lem:tight-slow:B2x-1} and \eqref{eq:lem:tight-slow:B2x-2} collectively control the term ${\bf B}^{(2x,n)}_{t,s}$.
    Combining them with  \eqref{eq:lem:tight-slow:BandPsi} and Markov's inequality yields the following upper bound
    \begin{align*}
        {\mathbb P} \left( 
        \| {\bar{\textnormal{Y}}}_{n}(s) - {\bar{\textnormal{Y}}}_{n}(t) \| \ge {\varepsilon} \right)
        & \le {\mathbb P} \left( 
        \| {\bf B}^{(3y,n)}_{t,s} \| \ge \frac{{\varepsilon}}{5} \right) + {\mathbb P} \left( 
        \| \mbox{\boldmath$\Psi$\unboldmath}^{(n)}_{t,s} \| \ge \frac{{\varepsilon}}{5} \right) 
        + {\mathbb P} \left( \| {\bf B}^{(2x,1)}_{n_0,n_1} \| \ge \frac{{\varepsilon}}{5} \right) \\
        & \qquad + {\mathbb P} \left( \| {\bf B}^{(2x,2)}_{n_0,n_1} \| \ge \frac{{\varepsilon}}{5} \right)
        + {\mathbb P} \left( \| {\bf B}^{(2x,n)}_{t,s} - {\bf B}^{(2x)}_{n_0, n_1} \| \ge \frac{{\varepsilon}}{5} \right)
        \\
        & \le \frac{25}{{\varepsilon}^2} \left( {\mathbb E}  \| {\bf B}^{(3y,n)}_{t,s} \|^2 + {\mathbb E} \| {\bf B}^{(2x,1)}_{n_0,n_1} \|^2 + {\mathbb E} \| {\bf B}^{(2x,n)}_{t,s} - {\bf B}^{(2x)}_{n_0, n_1} \|^2 \right) \\
        & \qquad + \frac{5^p}{{\varepsilon}^p} \left( {\mathbb E} \| \mbox{\boldmath$\Psi$\unboldmath}^{(n)}_{t,s} \|^p + {\mathbb E} \| {\bf B}^{(2x,2)}_{n_0,n_1} \|^p \right) \\
        & 
        \le 5^4 \left( \max_{3 \le i \le 7} K_i \right) \left[ \frac{ (s-t)^2 }{{\varepsilon}^2} + \frac{ (s-t)^\frac{p}{2} }{{\varepsilon}^p} \right].

    \end{align*}
    This upper bound verifies the second condition in Proposition~\ref{prop:tight-suff-slow}, and hence $\{ {\bar{\textnormal{Y}}}_{n}(\cdot) \}_{n=1}^\infty$ is tight.

