We first prove the part~(i). Throughout the proof, $C$ will represent a universal constant whose value may change from line to line, for the sake of convenience.
Because $f \in C^2_c({\mathbb R}^{d_x})$, $\| \nabla f(\cdot) \|$ and $\| \nabla^2 f(\cdot) \|$ are both bounded functions.

By  Taylor's theorem, we have
\begin{align}\label{eq:lem:generator-twotime:f}
    \begin{split}
        f({\check{x}}_{n+1}) - f({\check{x}}_{n})
        & = \inner{ \nabla f ({\check{x}}_{n}) }{ {\check{x}}_{n+1} - {\check{x}}_{n} } + \frac{1}{2} ( {\check{x}}_{n+1} - {\check{x}}_{n} )^\top \nabla^2 f({\check{x}}_{n}) ( {\check{x}}_{n+1} - {\check{x}}_{n} ) \\
        & \quad + \underbrace{ \frac{1}{2} ( {\check{x}}_{n+1} - {\check{x}}_{n} )^\top \left( \nabla^2 f({\check{u}}_{n}) - \nabla^2 f({\check{x}}_{n}) \right) ( {\check{x}}_{n+1} - {\check{x}}_{n} ) }_{R^f_{n,0}},
    \end{split}
\end{align}
where ${\check{u}}_{n}$ is a point between ${\check{x}}_{n}$ and ${\check{x}}_{n+1}$.
For the first term, we have
\begin{align}\label{eq:lem:generator-twotime:f1}
    {\mathbb E} [ \inner{ \nabla f ({\check{x}}_{n}) }{ {\check{x}}_{n+1} - {\check{x}}_{n} } | {\mathcal F}_{n} ]
    \overset{\eqref{eq:xcheck-twotime}}{=}
    - \alpha_{n} \inner{\nabla f({\check{x}}_{n})}{B_1 {\check{x}}_{n}} +
    \underbrace{ \inner{ \nabla f({\check{x}}_{n}) }{ {\mathbb E}[  R^x_{n}  | {\mathcal F}_{n} ] } }_{R^f_{n,1}}.
\end{align}
By Lemma~\ref{lem:check-twotime-xy}, we have
\begin{align}\label{eq:lem:generator-twotime:f2}
    {\mathbb E} | R^f_{n,1} |
    \lesssim {\mathbb E} \| {\mathbb E}[  R^x_{n}  | {\mathcal F}_{n} ] \| = o(\alpha_{n}).
\end{align}
For the second term, we have
\begin{align}
    & \qquad {\mathbb E} \left[ ( {\check{x}}_{n+1} - {\check{x}}_{n} )^\top \nabla^2 f({\check{x}}_{n}) ( {\check{x}}_{n+1} - {\check{x}}_{n} ) | {\mathcal F}_{n} \right] \nonumber \\
    & \overset{\eqref{eq:xcheck-twotime}}{=}
    \alpha_{n} {\mathbb E} \left[ \tilde{\xi}_{n}^\top \nabla^2 f({\check{x}}_{n}) \tilde{\xi}_{n} | {\mathcal F}_{n} \right] 
    + 2 \sqrt{\alpha_{n}} {\mathbb E} \left[ (-\alpha_{n} B_1 {\check{x}}_{n} + R^x_{n})^\top \nabla^2 f({\check{x}}_{n}) \tilde{\xi}_{n} | {\mathcal F}_{n} \right] \nonumber \\
    & \qquad + {\mathbb E}[ (-\alpha_{n} B_1 {\check{x}}_{n} + R^x_{n})^\top \nabla^2 f({\check{x}}_{n}) (-\alpha_{n} B_1 {\check{x}}_{n} + R^x_{n}) | {\mathcal F}_{n} ] \nonumber \\
    \begin{split}
        & = \alpha_{n} \mathrm{tr} ( \nabla^2 f({\check{x}}_{n})     \Sigma_{\xi} ) + \underbrace{ \alpha_{n} \mathrm{tr} \left( \nabla^2 f({\check{x}}_{n}) 
            ({\mathbb E} [ \tilde{\xi}_{n} \tilde{\xi}_{n}^\top | {\mathcal F}_{n} ]
            - \Sigma_{\xi} ) 
            \right) }_{2 R^f_{n,2}} 
