We first prove Part~(i).
For convenience, with $\Gamma^\alpha_{n,m}$ introduced in Definition~\ref{defn:time-inter}, we define the following notation
\begin{align*}
    \bar{N}^\alpha(n, t) := \min \left\{ m \ge n \colon \Gamma^\alpha_{n, m} \ge t \right\}.

\end{align*}
Then the filtration defined in \eqref{eq:filtration-main} can be written succinctly as ${\mathcal F}^{\bar{\textnormal{X}}}_{n,t} = {\mathcal F}_{ \bar{N}^\alpha(n, t) }$.
We construct ${\mathcal M}_{n}^f(t)$ as
\begin{align}\label{eq:Mnf-def}
    {\mathcal M}_{n}^f(t) = \ssum{k}{n}{\bar{N}^\alpha(n,t)-1} \big\{ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) - {\mathbb E}[ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) | {\mathcal F}_{k} ] \big\}.
\end{align}
Clearly, ${\mathcal M}_{n}^f(t)$ is adapted to the filtration $({\mathcal F}^{\bar{\textnormal{X}}}_{n,t})_{t \ge 0}$.
Next we verify that ${\mathcal M}_{n}^f(t)$ is a martingale w.r.t. $({\mathcal F}^{\bar{\textnormal{X}}}_{n,t})_{t \ge 0}$.

For any $t > s \ge 0$,
if $k \le \bar{N}^\alpha(n,s)-1$, then ${\check{x}}_{k}, {\check{x}}_{k+1} \in {\mathcal F}^{\bar{\textnormal{X}}}_{n,s}$ and ${\mathcal F}_k \subset {\mathcal F}^{\bar{\textnormal{X}}}_{n,s}$, implying
\[ {\mathbb E} \big\{ f({\check{x}}_{k+1}) {-} f({\check{x}}_{k}) {-} {\mathbb E}[ f({\check{x}}_{k+1}) {-} f({\check{x}}_{k}) | {\mathcal F}_{k} ] \big| {\mathcal F}^{\bar{\textnormal{X}}}_{n,s} \big\} {=} f({\check{x}}_{k+1}) {-} f({\check{x}}_{k}) {-} {\mathbb E}[ f({\check{x}}_{k+1}) {-} f({\check{x}}_{k})  | {\mathcal F}_{k} ].  \]
Otherwise, $k \ge \bar{N}^\alpha(n,s) $ and  ${\mathcal F}^{\bar{\textnormal{X}}}_{n,s} \subseteq {\mathcal F}_{k}$, implying
\[
{\mathbb E} \big\{ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) - {\mathbb E}[ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) | {\mathcal F}_{k} ]\, \big|\, {\mathcal F}^{\bar{\textnormal{X}}}_{n,s} \big\} = 0.
\]
Consequently,
\begin{align*}
    {\mathbb E} [ {\mathcal M}_{n}^f(t) | {\mathcal F}^{\bar{\textnormal{X}}}_{n,s} ]
    & = \ssum{k}{n}{\bar{N}^\alpha(n,t)-1} {\mathbb E} \big\{ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) - {\mathbb E}[ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) | {\mathcal F}_{k} ]\, \big|\, {\mathcal F}^{\bar{\textnormal{X}}}_{n,s} \big\} \\
    & = \ssum{k}{n}{\bar{N}^\alpha(n,s)-1} \big\{ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) - {\mathbb E}[ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) | {\mathcal F}_{k} ] \big\} 


    = {\mathcal M}_{n}^f(s),
\end{align*}
which implies that ${\mathcal M}_{n}^f (t)$ is a martingale w.r.t.\ ${\mathcal F}^{\bar{\textnormal{X}}}_{n,t}$.

Now we focus on the residual term ${\mathcal R}_{n}^f(t)$. For notational simplicity, we define $\overline{t}^\alpha_{n} = \Gamma^\alpha_{n, \bar{N}^\alpha(n,t)} 

$.
Then we have $\overline{t}^\alpha_{n} - \alpha_{\bar{N}^\alpha(n,t) - 1} < t \le \overline{t}^\alpha_{n}$.
With this notation and $\underline{t}^\alpha_{n}$ introduced in Definition~\ref{defn:time-inter},\footnote{In the notation $\underline{t}^\alpha_{n}$, we view $t$ as a variable.}
${\mathcal R}_{n}^f(t)$ can be expressed as
\begin{align}
    {\mathcal R}_{n}^f(t) 
    & = f( {\bar{\textnormal{X}}}_{n}(t) ) - f({\bar{\textnormal{X}}}_{n}(0) ) - \int_0^t {\mathcal A}^x f( {\bar{\textnormal{X}}}_{n}(s) )\, \mathrm{d} s - {\mathcal M}_{n} ^f(t)  \nonumber \\
    & \overset{\eqref{eq:Mnf-def}}{=} f({\bar{\textnormal{X}}}_{n}(t)) - f({\bar{\textnormal{X}}}_{n}(\overline{t}^\alpha_{n}) ) - \int_0^t {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \,\mathrm{d} s  + \ssum{k}{n}{\bar{N}^\alpha(n,t)-1} {\mathbb E} [ f({\check{x}}_{k+1}) - f({\check{x}}_{k}) | {\mathcal F}_{k} ] \nonumber \\
    & \overset{\eqref{eq:generator-twotime:x}}{=} f({\bar{\textnormal{X}}}_{n}(t)) - f({\bar{\textnormal{X}}}_{n}(\overline{t}^\alpha_{n}) )
    - \int_0^t {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \,\mathrm{d} s
    + \ssum{k}{n}{\bar{N}^\alpha(n,t)-1} \left( \alpha_{k} {\mathcal A}^x f({\check{x}}_{k}) + R^f_k \right) \nonumber \\
    & \overset{(a)}{=}

    f({\bar{\textnormal{X}}}_{n}(t)) - f({\bar{\textnormal{X}}}_{n}(\overline{t}^\alpha_{n}) )
    + \int_0^{\overline{t}^\alpha_{n}} \left( {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(\underline{s}^\alpha_{n}) ) - {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \right) \,\mathrm{d} s  \nonumber \\
    & \qquad   + \int_t^{\overline{t}^\alpha_{n}} {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \,\mathrm{d} s
    + \ssum{k}{n}{\bar{N}^\alpha(n,t) - 1} R^f_k, \label{eq:them:fclt-twotime:res}
\end{align}
where for step (a), we used Fact~\ref{fact2}~\ref{fact2-3} such that  $\alpha_{k} {\mathcal A}^x f({\check{x}}_{k}) = \int_{\Gamma^\alpha_{n,k}}^{\Gamma^\alpha_{n,k+1}}  {\mathcal A}^x f( {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_n ) ) \,\mathrm{d} s  $.

Notice that  $f \in C_c^2({\mathbb R}^{d_x})$.
For a fixed $t$,
to control ${\mathcal R}_{n}^f(t)$ in the $L_1$ sense, we need to control the following $L_1$ distances ${\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) \| $ and  ${\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \overline{s}^\alpha_{n} ) \|$ for any $s \in [0,\overline{t}_{n}^\alpha]$. 
From the definition of ${\bar{\textnormal{X}}}_{n}(\cdot)$ in \eqref{eq:def:xbar}, we have ${\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) = {\check{x}}_{N^\alpha(n,s)}$. Consequently, 
\begin{align*}
    {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n}  )
    = (s - \underline{s}^\alpha_{n} ) \left(- B_1 {\check{x}}_{N^\alpha(n,s) } + \frac{R^x_{N^\alpha (n,s)} }{ \alpha_{N^\alpha (n,s)} } \right) -  \frac{s - \underline{s}^\alpha_{n}}{ \sqrt{ \alpha_{N^\alpha(n,s)} } }  

    \tilde{\xi}_{N^\alpha(n,s)}. 
\end{align*}
It follows that for each $s \in [0, \overline{t}_{n}^\alpha] $, the following results hold
\begin{align*}
    {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) \| 
    & \le (s - \underline{t}^\alpha_{n} ) {\mathbb E} \left\| - B_1 {\check{x}}_{N^\alpha(n,s) } + \frac{R^x_{N^\alpha (n,s)} }{ \alpha_{N^\alpha (n,s)} } \right\| +  \frac{s - \underline{s}^\alpha_{n}}{ \sqrt{ \alpha_{N^\alpha(n,s)} } }  

    {\mathbb E} \| \tilde{\xi}_{N^\alpha(n,s)} \| \\
    & \overset{\eqref{eq:lem:tight-twotime:l2bound-x}}{\lesssim} (s - \underline{s}^\alpha_{n} ) + \sqrt{s - \underline{s}^\alpha_{n} } 
    \lesssim \sqrt{ \alpha_{N^\alpha(n,s)} }, \\
    {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \overline{s}^\alpha_{n} ) \| 
    & \le {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) \| + {\mathbb E} \| {\bar{\textnormal{X}}}_{n}( \overline{s}^\alpha_{n} ) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) \| \\
    & \le {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n}( \underline{s}^\alpha_{n} ) \| + ( \overline{s}^\alpha_{n} - \underline{s}^\alpha_{n} ) {\mathbb E} \left\| - B_1 {\check{x}}_{N^\alpha(n,s) } + \frac{R^x_{N^\alpha (n,s)} }{ \alpha_{N^\alpha (n,s)} } \right\| \\
    & \qquad +  \frac{ \overline{s}^\alpha_{n} - \underline{s}^\alpha_{n}}{ \sqrt{ \alpha_{N^\alpha(n,s)} } }  

    {\mathbb E} \| \tilde{\xi}_{N^\alpha(n,s)} \| \\
    & \lesssim \sqrt{ \alpha_{N^\alpha(n,s)} }.
\end{align*}
Since $f \in C_c^2({\mathbb R}^{d_x})$, it follows that
\begin{align}\label{eq:thm:fclt-twotime:res1}
    \begin{split}
        {\mathbb E} | f({\bar{\textnormal{X}}}_{n}(t)) - f({\bar{\textnormal{X}}}^{(n)}_{\overline{t}^\alpha_{n}}) |
        & \lesssim {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(t) - {\bar{\textnormal{X}}}^{(n)}_{\overline{t}^\alpha_{n} } \| \lesssim \sqrt{\alpha_{N^\alpha(n,t)}} = o(1), \\
        {\mathbb E} \left| \int_t^{\overline{t}^\alpha_{n}} {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \,\mathrm{d} s \right|
        & \lesssim \int_t^{\overline{t}^\alpha_{n}} 1 \,\mathrm{d} s 

        = o(1), \\
        {\mathbb E} \left| \int_0^{\overline{t}^\alpha_{n}} \left( {\mathcal A}^x f({\bar{\textnormal{X}}}_{n} (\underline{s}^\alpha_{n}) ) - {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s)) \right) \,\mathrm{d} s \right|
        & \lesssim \int_0^{\overline{t}^\alpha_{n}} {\mathbb E} \| {\bar{\textnormal{X}}}_{n}(s) - {\bar{\textnormal{X}}}_{n} (\underline{s}^\alpha_{n} ) \| \,\mathrm{d} s \\
        &   \lesssim \int_0^{\overline{t}^\alpha_{n}} \sqrt{\alpha_{N^\alpha(n,s)} } ds \lesssim \sqrt{\alpha_{n}} = o(1).
    \end{split}
\end{align}
Moreover, for a fixed $t$, Lemma~\ref{lem:generator-twotime} implies
\begin{align}\label{eq:thm:fclt-twotime:res2}
    {\mathbb E} \left| \ssum{k}{n}{\bar{N}^\alpha(n,t) - 1} R^f_k \right|
    \le \ssum{k}{n}{\bar{N}^\alpha(n,t) - 1} \alpha_{k} {\mathbb E} \left| \frac{R^f_k}{\alpha_{k}} \right|
    \le \sup_{k' \ge n} {\mathbb E} \left| \frac{R^f_{k'}}{\alpha_{k'}} \right| \cdot \ssum{k}{n}{\bar{N}^\alpha(n,t) - 1} \alpha_{k} \lesssim o(1).
\end{align}
Plugging \eqref{eq:thm:fclt-twotime:res1} and \eqref{eq:thm:fclt-twotime:res2} into \eqref{eq:them:fclt-twotime:res} yields that for a fixe $t$, ${\mathbb E} | {\mathcal R}_{n}^f(t) | \to 0$ as $n \to \infty$.
